struct S;
fn g() {}
fn f1() -> u8 { let x = 1; x }
fn f2() { let a = 1; let b = a; b; }
fn f3() -> u8 { 5 }
fn f4() { let a = 1; }
fn f5(x: u8) { match x { _ => {} } }
trait T {
    fn a(&self);
    fn b(&self);
}
impl S {
    fn c() {}
}
impl T for S {
    fn a(&self) {}
    fn b(&self) {}
}
