// `macro_rules` scopes across modules, `#[macro_use]`, `$crate` and `#[macro_export]`.
#![feature(no_core)]
#![no_core]
#[macro_use]
mod a {
    macro_rules! from_a { () => {} }
    #[macro_export]
    macro_rules! exported {
        () => { fn from_exported() { $crate::a::b::f() } }
    }
    pub mod b {
        pub fn f() {}
    }
}
mod c {
    fn g() {
        fn from_exported() { crate::a::b::f() }
        from_exported();
    }
    macro_rules! local { () => {} }
}
fn from_exported() { crate::a::b::f() }

